// Correction round. All four raw-store sites, the copy entry, and completion.
// Imports pose.mjs unchanged. Stock image. NVRAM off. No overlay.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/trace_stores_r1.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { attachPose, POSES } from './pose.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/trace_stores_r1.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
process.env.OM_EMU_NVRAM = 'off';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const IMAGE_BASE = 0x60021020;
const dis = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
const GETTER = 0x60063380;
const COPY = 0x6006a9c1;
const COMPLETION = 0x6006a8ca;
const STORES = [
  [0x60077ff6, 'store-ff6'],
  [0x60078025, 'store-025'],
  [0x60078052, 'store-052'],
];
const OUT = resolve('work/out/trace-stores-r1.jsonl');
let DEADLINE = Date.now() + 8 * 60 * 1000;

const image = readFileSync(resolve('inputs/00_0100_50000020.decoded.bin'));
function descriptors(keys) {
  const tables = [0x60095584, 0x600b8f54, 0x600bb5ec, 0x600bda78, 0x600e4bec];
  const want = new Set(keys);
  const found = {};
  for (const start of tables) {
    let a = start;
    for (let n = 0; n < 5000 && want.size; n++) {
      const off = a - IMAGE_BASE;
      if (off < 0 || off + 4 > image.length) break;
      const key = image[off] | (image[off + 1] << 8);
      if (key === 0) break;
      const count = image[off + 2] | (image[off + 3] << 8);
      const width = (key & 3) || 4;
      if (want.has(key)) {
        found[key] = { record: a, count, width, header: image.subarray(off, off + 4).toString('hex') };
        want.delete(key);
      }
      const nxt = (a + 4 + count * width + 3) & ~3;
      if (nxt <= a) break;
      a = nxt;
    }
  }
  return found;
}
const desc = descriptors([0xe91, 0x90a1, 0x99a1, 0x5962]);
if (!desc[0xe91] || desc[0xe91].count !== 12 || desc[0xe91].record !== 0x600e4c2c) {
  throw new Error('e91 descriptor ' + JSON.stringify(desc[0xe91]));
}
if (!desc[0x90a1] || desc[0x90a1].count !== 2) throw new Error('90a1 descriptor');
if (desc[0x99a1].count !== 8 || desc[0x5962].count !== 6) throw new Error('bank descriptor');

const { loadNand, loadImage, loadBlock, createHash: fwHash } = await use('checks/lib/env.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
const seeds = [
  resolve(checkout, 'emu/checks/lib/env.mjs'),
  resolve(checkout, 'emu/src/lab/player.mjs'),
  resolve(checkout, 'emu/src/lab/play.mjs'),
  resolve(checkout, 'emu/scenarios/session_replay.mjs'),
  fileURLToPath(import.meta.url),
];
const seen = new Map();
const queue = [...seeds];
while (queue.length) {
  const file = queue.pop();
  if (!file || seen.has(file) || !existsSync(file)) continue;
  const data = readFileSync(file);
  seen.set(file, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
  IMPORT_RE.lastIndex = 0;
  const text = data.toString('utf8');
  let match;
  while ((match = IMPORT_RE.exec(text))) {
    const next = resolveSpec(file, match[1]);
    if (next) queue.push(next);
  }
}
writeFileSync(resolve('work/out/trace-stores-r1-imports.json'), JSON.stringify(
  [...seen.entries()].map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), sha256: meta.sha256, bytes: meta.bytes })).sort((a, b) => a.path.localeCompare(b.path)),
  null, 2,
) + '\n');

const lines = [];
const log = (row) => {
  lines.push(JSON.stringify(row));
  writeFileSync(OUT, lines.join('\n') + '\n');
  console.log(JSON.stringify({ step: row.step, ok: row.ok, raw: row.raw, stores: row.storeNames || null, error: row.error || null }));
};
const msg = (e) => String(e && e.stack ? e.stack : e).slice(0, 500);
const reasons = [];

const fw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(fw.rom);
const pl = new Player(
  { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
  {
    ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
    machine: { coverage: { mark() {}, stub() {} } }, patch: fw.summary, patchRanges: fw.changed, loaded: 'on',
  },
);
pl.camapp_components = true;
pl.camapp_native_tra = true;

let failed = null;
try {
  log({ step: 'open', descriptors: desc });
  pl.open_session();
  DEADLINE = Date.now() + 6 * 60 * 1000;
  const s = pl.session;
  const l = s.lab;
  const pose = attachPose(l);
  const hits = [];
  let completion = 0;
  let copy = 0;
  const noteStore = (name) => (_lab, r) => {
    if (hits.length < 80) hits.push({ name, d0: r.d0 & 0xffff, d1: r.d1 & 0xffff });
  };
  for (const [addr, name] of STORES) l.observe(dis(addr), noteStore(name), 'obs-' + name);
  l.observe(dis(COPY), () => { copy += 1; }, 'obs-copy-r1');
  l.observe(dis(COMPLETION), () => { completion += 1; }, 'obs-completion-r1');
  let reading = false;
  const readKey = (key, index) => {
    reading = true;
    try { return l.call(dis(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff; }
    finally { reading = false; }
  };
  void reading;
  const e91 = () => Array.from({ length: desc[0xe91].count }, (_, i) => readKey(0xe91, i));
  const subject = () => Array.from({ length: desc[0x90a1].count }, (_, i) => readKey(0x90a1, i));
  const idle = (ms) => {
    const to = l.lab_time() + ms * 1e6;
    while (l.lab_time() < to && Date.now() < DEADLINE) s.idle_slice(Math.min(to, l.lab_time() + 50e6));
  };

  idle(300);
  const subject0 = subject();
  if (subject0.some((v) => v !== 0)) reasons.push('subject detect 0x90a1 ' + subject0.join(','));
  log({ step: 'subject', values: subject0, e91: e91() });

  // Same order as trace-pose-s4, so a lens-up sample follows landscape's index 1.
  const samples = [
    ['x+', POSES.exif6.x, POSES.exif6.y, POSES.exif6.z, 1, 2, 6],
    ['x-', POSES.exif8.x, POSES.exif8.y, POSES.exif8.z, 3, 4, 8],
    ['y+', 0, 16384, 0, 2, 3, 3],
    ['y-', POSES.landscape.x, POSES.landscape.y, POSES.landscape.z, 0, 1, 1],
    ['z+', 0, 0, 16384, 4, 1, 1],
    ['z-', 0, 0, -16384, 5, 1, 1],
  ];
  for (const [name, x, y, z, raw, index, exif] of samples) {
    if (Date.now() > DEADLINE) { reasons.push('deadline before ' + name); break; }
    hits.length = 0;
    const pubBefore = pose.publishes.length;
    const copyBefore = copy;
    const compBefore = completion;
    pose.setSample(x, y, z);
    const fired = pose.deliver();
    idle(400);
    const now = pose.read();
    const pubs = pose.publishes.slice(pubBefore);
    const storeNames = [...new Set([...hits.map((h) => h.name), ...pubs.map(() => 'store-05e')])];
    const storedValues = [...hits.map((h) => h.name === 'store-ff6' || h.name === 'store-025' || h.name === 'store-052' ? h.d1 : h.d0), ...pubs];
    const row = {
      step: 'pose-' + name, raw: now.raw, index: now.index, exif: now.exif,
      unpacked: now.unpacked, cache: now.cache, e91: e91(),
      readFired: fired.readFired, completion: completion - compBefore, copy: copy - copyBefore,
      hits, publishes: pubs, storeNames,
    };
    log(row);
    if (!fired.readFired) reasons.push(name + ' register read did not fire');
    if (completion - compBefore < 1) reasons.push(name + ' completion not reached');
    if (now.unpacked[0] !== x || now.unpacked[1] !== y || now.unpacked[2] !== z) reasons.push(name + ' unpacked ' + now.unpacked.join(','));
    if (now.raw !== raw) reasons.push(name + ' raw ' + now.raw + ' expected ' + raw);
    if (now.index !== index) reasons.push(name + ' index ' + now.index + ' expected ' + index);
    if (now.exif !== exif) reasons.push(name + ' exif ' + now.exif + ' expected ' + exif);
    if (!storedValues.includes(raw)) reasons.push(name + ' no store wrote ' + raw);
  }
  const subject1 = subject();
  if (subject1.some((v) => v !== 0)) reasons.push('subject detect changed ' + subject1.join(','));
  const ok = reasons.length === 0;
  log({ step: 'done', ok, reasons, subject: subject1 });
  if (!ok) process.exitCode = 1;
} catch (e) {
  failed = e;
  log({ step: 'fail', ok: false, error: msg(e) });
  process.exitCode = 1;
} finally {
  try { if (pl.session) pl.close_session(); } catch { /* already closed */ }
}
if (failed) process.exitCode = 1;
